modes.detail:
// ============ 核心思路 ============
//
// 排序的对象从"元素数组"换成了"下标数组"。
//
// 比较的时候，不再是比 A[j-1] 和 A[tmp]，
// 而是比 **A[table[j-1]] 和 A[table[i]]** —— 绕一层下标去看元素。
//
// 搬动的时候，搬的是 **table 里的下标**，不是元素本身。
//
// 所以整个算法只需要改两处：
//
//   比较处：加一层 table 间接访问
//   搬动处：搬 table 而不是搬 A
//
// 本模块用的是插入排序的框架（因为它最简单、也最适合"搬动很少"的场景）。
// 换成别的排序算法也一样，只要记住"比较和搬动都要通过 table"。
//
// ============ 一个容易搞混的地方 ============
//
// 排序的**目标**是 table 变成"按元素大小排列的下标序列"。
//
// 比如 A = { 30, 10, 40, 20 }：
//
//   最小的 10 在下标 1，然后是 20 在下标 3、30 在下标 0、40 在下标 2
//
//   所以排完之后 table = { 1, 3, 0, 2 }
//
// 读的时候：A[table[0]] = A[1] = 10，A[table[1]] = A[3] = 20…… 依次递增。

// 表排序：把"访问顺序"排进 table，A 本身不动
void TableSort(ElementType A[], int N, int table[])
{
// 循环用
    int i, j;
// 临时存一个下标
    int tmp;

// 初始化：一开始"第 i 小的就是第 i 个"
    for (i = 0; i < N; i++)
    {
        table[i] = i;
    }

// 用插入排序的框架，对 table 排序
    for (i = 1; i < N; i++)
    {
// 取出当前下标
        tmp = table[i];

// 比较时套一层 table —— 注意这里是 A[table[j-1]] 和 A[tmp]
// tmp 本身就是一个下标，所以直接 A[tmp] 就是它指向的元素。
        for (j = i; j > 0 && A[table[j - 1]] > A[tmp]; j--)
        {
// 搬动的是下标，不是元素
            table[j] = table[j - 1];
        }

// 下标落位
        table[j] = tmp;
    }
}

modes.short:
// 表排序：把"访问顺序"排进 table，A 本身不动
void TableSort(ElementType A[], int N, int table[])
{
// 循环用
    int i, j;
// 临时存一个下标
    int tmp;

// 初始化：一开始"第 i 小的就是第 i 个"
    for (i = 0; i < N; i++)
    {
        table[i] = i;
    }

// 用插入排序的框架，对 table 排序
    for (i = 1; i < N; i++)
    {
// 取出当前下标
        tmp = table[i];

// 比较时套一层 table —— 注意这里是 A[table[j-1]] 和 A[tmp]
        for (j = i; j > 0 && A[table[j - 1]] > A[tmp]; j--)
        {
// 搬动的是下标，不是元素
            table[j] = table[j - 1];
        }

// 下标落位
        table[j] = tmp;
    }
}

