// ummary | 打印数组、检查是否有序。
// 表排序有个特殊的输出方式：既打印元素本身，也打印 table 指出的顺序。
// 因为"表排序之后数组是乱的，但按 table 读是有序的" —— 这一点必须看清楚。

void PrintArray(const ElementType A[], int N)
{
// 循环用
    int i;

    printf("[");
    for (i = 0; i < N; i++)
    {
        printf("%d", A[i]);
        if (i < N - 1)
        {
            printf(", ");
        }
    }
    printf("]");
}

// 检查是否有序
int IsSorted(const ElementType A[], int N)
{
// 循环用
    int i;

    for (i = 0; i + 1 < N; i++)
    {
        if (A[i] > A[i + 1])
        {
            return 0;
        }
    }
    return 1;
}

// 按 table 给出的顺序打印元素
// 这是表排序的正确读法：数组本身乱着，但按 table 读出来是有序的。
void PrintByTable(const ElementType A[], int table[], int N)
{
// 循环用
    int i;

    printf("[");
    for (i = 0; i < N; i++)
    {
// 绕一层 table 去访问元素
        printf("%d", A[table[i]]);
        if (i < N - 1)
        {
            printf(", ");
        }
    }
    printf("]");
}

// 检查"按 table 读出来"是不是有序
int IsSortedByTable(const ElementType A[], int table[], int N)
{
// 循环用
    int i;

    for (i = 0; i + 1 < N; i++)
    {
        if (A[table[i]] > A[table[i + 1]])
        {
            return 0;
        }
    }
    return 1;
}

