#include <stdio.h>
#include <stdlib.h>

/* ======== [已给出] 模块 01 typedef ======== */

typedef int ElementType;

#define RADIX 10

#define MAXD 4

#define MAXN 100

#define OK 1
#define ERROR 0
typedef int Status;

/* ======== [已给出] 模块 02 TableSort ======== */

void TableSort(ElementType A[], int N, int table[])
{
    int i, j;
    int tmp;

    for (i = 0; i < N; i++)
    {
        table[i] = i;
    }

    for (i = 1; i < N; i++)
    {
        tmp = table[i];

        for (j = i; j > 0 && A[table[j - 1]] > A[tmp]; j--)
        {
            table[j] = table[j - 1];
        }

        table[j] = tmp;
    }
}

/* ====================================================================
 *  轮到你了：模块 06  PrintArray
 *  作用：打印数组、检查有序、按 table 打印。
 *  提示：先写函数签名，再写循环定位，最后写指针操作。
 *  写完按 Ctrl + Enter 编译运行，点"对比"看与参考实现的差异。
 * ==================================================================== */



/* ======== 测试驱动（已给出，可自行修改） ======== */
/* 验证 PrintArray / IsSorted / PrintByTable / IsSortedByTable */
int main(void)
{
    ElementType a[] = { 30, 10, 40, 20 };
    ElementType b[] = { 1, 2, 3, 4 };
    int table[4];
    int i;

    printf("a = "); PrintArray(a, 4);
    printf("  有序: %s\n", IsSorted(a, 4) ? "是" : "不是");

    printf("b = "); PrintArray(b, 4);
    printf("  有序: %s\n\n", IsSorted(b, 4) ? "是" : "不是");

    TableSort(a, 4, table);
    printf("表排序 a 之后：\n");
    printf("  A 本身:       "); PrintArray(a, 4);
    printf("  ← 还是乱的\n");
    printf("  按 table 读:  "); PrintByTable(a, table, 4);
    printf("  ← 有序\n");
    printf("  IsSorted(A)          = %s  ← 直接看数组是乱的\n", IsSorted(a, 4) ? "真" : "假");
    printf("  IsSortedByTable(A)   = %s  ← 按 table 看才有意义\n",
           IsSortedByTable(a, table, 4) ? "真" : "假");
    printf("\n（这就是表排序的特点：数组乱着，但「访问顺序」是有序的）\n");

    (void)i;
    return 0;
}

modes.detail:
// ============ 怎么看这两个算法 ============
//
// **表排序**的重点是：跑完之后 `A` 本身还是乱的，但 `A[table[0]]`、
// `A[table[1]]`…… 读出来是有序的。这就是"间接排序"。
//
// **基数排序**的重点是：整个过程一次比较都没有，只有"取某一位"和
// "分桶收集"。所以它的复杂度里没有 log n。

// 主函数
int main(void)
{
// 表排序的测试数据
    ElementType a[] = { 30, 10, 40, 20, 50 };
// table
    int table[5];
// 基数排序的测试数据
    ElementType b[] = { 1234, 5, 21, 0, 99, 1000, 7, 456 };
// 长度
    int nb = 8;
// 循环用
    int i;

// ===== 表排序 =====
    printf("=== 表排序 ===\n");
    printf("原始 A: ");
    PrintArray(a, 5);
    printf("\n\n");

    TableSort(a, 5, table);

    printf("排完之后 A 本身: ");
    PrintArray(a, 5);
    printf("   ← 一个都没动！\n");
    printf("table:           [");
    for (i = 0; i < 5; i++)
    {
        printf("%d%s", table[i], i < 4 ? ", " : "");
    }
    printf("]\n");
    printf("按 table 读 A:   ");
    PrintByTable(a, table, 5);
    printf("   ← 有序了\n");
    printf("按 table 读是有序: %s\n\n", IsSortedByTable(a, table, 5) ? "是" : "不是");

// 环重排
    printf("--- 如果需要元素本身也有序，就做环重排 ---\n");
    printf("重排前 A: ");
    PrintArray(a, 5);
    printf("\n");
    Rearrange(a, 5, table);
    printf("重排后 A: ");
    PrintArray(a, 5);
    printf("   %s\n", IsSorted(a, 5) ? "有序 ✓" : "还是乱的 ✗");
    printf("（环移动是原地完成的，不需要额外数组）\n\n");

// ===== 基数排序 =====
    printf("=== 基数排序 ===\n");
    printf("原始: ");
    PrintArray(b, nb);
    printf("\n");
    printf("（最大 4 位数，所以做 4 轮：个位 → 十位 → 百位 → 千位）\n\n");

// 手工演示前两轮
    {
        ElementType c[MAXN];
        int count[RADIX];
        ElementType buckets[RADIX][MAXN];
        ElementType tmp[MAXN];
        int d, j, di, pos;

        for (i = 0; i < nb; i++) c[i] = b[i];

        for (d = 1; d <= 2; d++)
        {
            for (i = 0; i < RADIX; i++) count[i] = 0;
            for (i = 0; i < nb; i++)
            {
                di = GetDigit(c[i], d);
                buckets[di][count[di]++] = c[i];
            }
            pos = 0;
            for (i = 0; i < RADIX; i++)
            {
                for (j = 0; j < count[i]; j++) tmp[pos++] = buckets[i][j];
            }
            for (i = 0; i < nb; i++) c[i] = tmp[i];

            printf("第 %d 轮（看%s位）之后: ", d, d == 1 ? "个" : "十");
            PrintArray(c, nb);
            printf("\n");
        }
        printf("\n");
    }

// 完整跑一遍
    RadixSort(b, nb);
    printf("排完: ");
    PrintArray(b, nb);
    printf("   %s\n", IsSorted(b, nb) ? "有序 ✓" : "还是乱的 ✗");

// 总结
    printf("\n=== 两个算法的共同点：绕开 O(n log n) ===\n");
    printf("  表排序  ：比较的本质没变，但「搬动」的代价从几百字节降到 4 字节\n");
    printf("  基数排序：**完全不比较**，靠逐位分桶，O(d(n+r))\n");
    printf("\n基数排序为什么是对的？因为「分配-收集」是稳定的，\n");
    printf("所以低位排好的顺序在高位相同时不会被打乱。\n");
    printf("（这也是它必须用稳定排序的原因）\n");

// 正常结束
    return 0;
}

