#include <stdio.h>
#include <stdlib.h>

/* ======== [已给出] 模块 01 typedef ======== */

typedef int ElementType;

#define RADIX 10

#define MAXD 4

#define MAXN 100

#define OK 1
#define ERROR 0
typedef int Status;

/* ======== [已给出] 模块 02 TableSort ======== */

void TableSort(ElementType A[], int N, int table[])
{
    int i, j;
    int tmp;

    for (i = 0; i < N; i++)
    {
        table[i] = i;
    }

    for (i = 1; i < N; i++)
    {
        tmp = table[i];

        for (j = i; j > 0 && A[table[j - 1]] > A[tmp]; j--)
        {
            table[j] = table[j - 1];
        }

        table[j] = tmp;
    }
}

/* ======== [已给出] 模块 03 Rearrange ======== */

void Rearrange(ElementType A[], int N, int table[])
{
    int i, k, next;
    ElementType tmp;

    for (i = 0; i < N; i++)
    {
        if (table[i] != i)
        {
            tmp = A[i];
            k = i;

            while (table[k] != i)
            {
                A[k] = A[table[k]];

                next = k;
                k = table[k];

                table[next] = next;
            }

            A[k] = tmp;
            table[k] = k;
        }
    }
}

/* ======== [已给出] 模块 04 GetDigit ======== */

int GetDigit(int x, int d)
{
    int i;

    for (i = 1; i < d; i++)
    {
        x /= 10;
    }

    return x % RADIX;
}

/* ======== [已给出] 模块 05 RadixSort ======== */

void RadixSort(ElementType A[], int N)
{
    ElementType buckets[RADIX][MAXN];
    int count[RADIX];
    ElementType tmp[MAXN];
    int d;
    int i, j;
    int di;
    int pos;

    for (d = 1; d <= MAXD; d++)
    {
        for (i = 0; i < RADIX; i++)
        {
            count[i] = 0;
        }

        for (i = 0; i < N; i++)
        {
            di = GetDigit(A[i], d);
            buckets[di][count[di]++] = A[i];
        }

        pos = 0;
        for (i = 0; i < RADIX; i++)
        {
            for (j = 0; j < count[i]; j++)
            {
                tmp[pos++] = buckets[i][j];
            }
        }

        for (i = 0; i < N; i++)
        {
            A[i] = tmp[i];
        }
    }
}

/* ======== [已给出] 模块 06 PrintArray ======== */

void PrintArray(const ElementType A[], int N)
{
    int i;

    printf("[");
    for (i = 0; i < N; i++)
    {
        printf("%d", A[i]);
        if (i < N - 1)
        {
            printf(", ");
        }
    }
    printf("]");
}

int IsSorted(const ElementType A[], int N)
{
    int i;

    for (i = 0; i + 1 < N; i++)
    {
        if (A[i] > A[i + 1])
        {
            return 0;
        }
    }
    return 1;
}

void PrintByTable(const ElementType A[], int table[], int N)
{
    int i;

    printf("[");
    for (i = 0; i < N; i++)
    {
        printf("%d", A[table[i]]);
        if (i < N - 1)
        {
            printf(", ");
        }
    }
    printf("]");
}

int IsSortedByTable(const ElementType A[], int table[], int N)
{
