#include <stdio.h>
#include <stdlib.h>

// ============ 表排序为什么有用 ============
//
// 假设要排一个"学生表"，每个学生有姓名、学号、成绩、备注……
// 一个结构体可能有几百字节。
//
// 如果直接搬动这些结构体：
//
//   排序 1000 个学生，移动次数 O(n²) 次 × 每次搬 500 字节 = 极其昂贵
//
// 但如果只搬"下标"：
//
//   每次只搬 4 字节（一个 int），速度直接差上百倍
//
// 排完之后得到一个"访问顺序表"：
//
//   table = [3, 0, 4, 1, 2]
//   意思是"第 1 小的元素在下标 3、第 2 小的在下标 0……"
//
// **需要的时候按 table 的顺序去访问就行了，元素本身一个都没动。**
//
// ============ 基数排序的两个关键参数 ============
//
//   **基数 r**：每一位有多少种取值。十进制就是 10。
//   **位数 d**：最大数有多少位。最大 9999 就是 4 位。
//
// 复杂度是 **O(d(n + r))**。
//
// 注意它**和 n log n 无关** —— 只要 d 是常数，它就是**线性**的。
// 这就是"绕开比较排序下限"的办法：它压根不比较。

// 元素类型
typedef int ElementType;

// 基数：十进制数每一位有 10 种可能（0~9）
#define RADIX 10

// 最大位数：本节的测试数据最大 9999，所以是 4 位
#define MAXD 4

// 数组的最大长度（桶要用）
#define MAXN 100

// 状态码
#define OK 1
#define ERROR 0
typedef int Status;

// ============ 核心思路 ============
//
// 排序的对象从"元素数组"换成了"下标数组"。
//
// 比较的时候，不再是比 A[j-1] 和 A[tmp]，
// 而是比 **A[table[j-1]] 和 A[table[i]]** —— 绕一层下标去看元素。
//
// 搬动的时候，搬的是 **table 里的下标**，不是元素本身。
//
// 所以整个算法只需要改两处：
//
//   比较处：加一层 table 间接访问
//   搬动处：搬 table 而不是搬 A
//
// 本模块用的是插入排序的框架（因为它最简单、也最适合"搬动很少"的场景）。
// 换成别的排序算法也一样，只要记住"比较和搬动都要通过 table"。
//
// ============ 一个容易搞混的地方 ============
//
// 排序的**目标**是 table 变成"按元素大小排列的下标序列"。
//
// 比如 A = { 30, 10, 40, 20 }：
//
//   最小的 10 在下标 1，然后是 20 在下标 3、30 在下标 0、40 在下标 2
//
//   所以排完之后 table = { 1, 3, 0, 2 }
//
// 读的时候：A[table[0]] = A[1] = 10，A[table[1]] = A[3] = 20…… 依次递增。

// 表排序：把"访问顺序"排进 table，A 本身不动
void TableSort(ElementType A[], int N, int table[])
{
// 循环用
    int i, j;
// 临时存一个下标
    int tmp;

// 初始化：一开始"第 i 小的就是第 i 个"
    for (i = 0; i < N; i++)
    {
        table[i] = i;
    }

// 用插入排序的框架，对 table 排序
    for (i = 1; i < N; i++)
    {
// 取出当前下标
        tmp = table[i];

// 比较时套一层 table —— 注意这里是 A[table[j-1]] 和 A[tmp]
// tmp 本身就是一个下标，所以直接 A[tmp] 就是它指向的元素。
        for (j = i; j > 0 && A[table[j - 1]] > A[tmp]; j--)
        {
// 搬动的是下标，不是元素
            table[j] = table[j - 1];
        }

// 下标落位
        table[j] = tmp;
    }
}

// ============ 为什么要"重排" ============
//
// 表排序的好处是"不动元素"。但有时候下游代码就是要一个物理有序的数组
// （比如要传给一个不知道 table 的库函数），那就得真搬。
//
// 这时候有个讲究：**不能简单地按 table 一个个搬过去**，那样需要一个
// 同等大小的临时数组。而"环移动"可以**原地完成**，只用 O(1) 的额外空间。
//
// ============ 什么是"环" ============
//
// 把 table 看成一个置换：table[i] 表示"位置 i 应该放原来第 table[i] 个元素"。
//
// 拿 A = { 30, 10, 40, 20 }（table = { 1, 3, 0, 2 }）举例：
//
//   位置 0 要放原来下标 1 的（10）
//   位置 1 要放原来下标 3 的（20）
//   位置 3 要放原来下标 2 的（40）
//   位置 2 要放原来下标 0 的（30）
//
// 追着看：0 → 1 → 3 → 2 → 0，**绕回了起点** —— 这是一个 4 个元素的环。
//
// 另一个例子 table = { 0, 2, 1 }：
//
//   位置 0 已经对了（table[0] = 0），不动
//   位置 1 ↔ 位置 2 互换，这是一个 2 个元素的环
//
// 做法就是：**沿着环一个个搬，最后把空出来的位置填上**。
// 每处理完一个环，这些位置就都到位了，后面不用再看。
//
// ============ 复杂度 ============
//
// 每个元素最多被搬一次（每个环里的元素只走一遍），所以是 **O(n)**。
//
// 比"另开一个数组再拷回来"省了 O(n) 的空间。

// 按 table 把 A 重排成物理有序（原地，用环移动）
// 注意：执行后 table 会被破坏成"已经是单位置换"的状态
void Rearrange(ElementType A[], int N, int table[])
{
// 循环用
    int i, k, next;
// 暂存元素
    ElementType tmp;

    for (i = 0; i < N; i++)
    {
// table[i] == i 说明这个位置已经对了，跳过
        if (table[i] != i)
        {
// 把位置 i 的元素先抱出来——它要搬到别处去
            tmp = A[i];
            k = i;

// 沿着环往前推，直到绕回起点
            while (table[k] != i)
            {
// 把"应该放到 k 位置"的那个元素搬过来
                A[k] = A[table[k]];

// 记住当前位置，然后跳到下一个
                next = k;
                k = table[k];

// 这个位置处理完了，标记成"已就位"
                table[next] = next;
            }

// 环绕回来了，把最开始抱出来的元素放进空位
            A[k] = tmp;
            table[k] = k;
        }
    }
}

// ============ 怎么取出第 d 位 ============
//
// 两步：
//
//   ① **先除掉低位**：x /= 10 做 d-1 次，把要的那一位挪到个位
//   ② **再取个位**：x % 10
//
// 举例，取 1234 的第 2 位：
//
//   除以 10 一次 → 123
//   123 % 10 → 3      ✓
//
// ============ 为什么基数排序要用它 ============
//
// 基数排序每一轮只看"某一位"。第 1 轮看个位、第 2 轮看十位……
//
// 所以需要频繁回答"这个数的第 d 位是几"，GetDigit 就是干这个的。

// 取非负整数 x 的第 d 位（d 从 1 开始，d=1 是个位）
int GetDigit(int x, int d)
{
// 循环用
    int i;

// 先把低 d-1 位除掉
    for (i = 1; i < d; i++)
    {
        x /= 10;
    }

// 取个位
    return x % RADIX;
}

// ============ 一轮"分配-收集"在做什么 ============
//
//   ① **分配**：按当前位上的数字，把每个元素扔进对应的桶
//              （0~9 一共 10 个桶）
//   ② **收集**：按桶号从 0 到 9，把桶里的元素依次取回来
//
// 走一遍 { 1234, 0005, 0021, 0000 }（按 4 位看）：
//
//   **第 1 轮（个位）**：
//     4 进 4 号桶、5 进 5 号桶、1 进 1 号桶、0 进 0 号桶
//     收集：0 号桶的 0000 → 1 号桶的 0021 → 4 号桶的 1234 → 5 号桶的 0005
//     结果：0000, 0021, 1234, 0005
//
//   **第 2 轮（十位）**：
//     0000 的十位是 0 → 0 号桶
//     0021 的十位是 2 → 2 号桶
//     1234 的十位是 3 → 3 号桶
//     0005 的十位是 0 → 0 号桶
//
//     收集 0 号桶：[0000, 0005]（注意顺序！）→ 2 号桶、3 号桶
//     结果：0000, 0005, 0021, 1234
//
//   继续做百位、千位…… 最后就是完全有序的
//
// ============ 为什么"低位优先"（LSD）能对 ============
//
// 这是最反直觉的地方：先按个位排，后面按十位百位排的时候，
// 个位的顺序**不会被打乱吗**？
//
// 不会，**前提是每一轮都是稳定的**。
//
// 想一下第 3 轮（百位）做完之后是什么状态：
//
//   所有元素按百位分好了组，而**每组内部**的顺序，
//   是上一轮（十位）做完时的顺序 —— 也就是"按十位有序"。
//
//   而十位有序的组内部，又是"按个位有序"的。
//
// 所以三轮做完之后：**先按百位、百位相同再看十位、十位相同再看个位** ——
// 这正是"从高位到低位逐个比较"的效果，也就是完全有序。
//
// 一句话：**LSD 的正确性完全建立在"每一轮都是稳定排序"之上。**
//
// 而"分配-收集"这个动作恰好是稳定的：
// 同一个桶里，先进去的先被取出来。所以顺序不会乱。
//
// ============ 复杂度 ============
//
// 每轮做 n 次分配 + n 次收集，共 d 轮，所以是 **O(d(n + r))**。
//
// 只要最大位数 d 是常数（比如都是 4 位数），它就是**线性**的。
// 这是"绕开比较排序 O(n log n) 下限"的经典办法。

// 基数排序（低位优先）
void RadixSort(ElementType A[], int N)
{
// 桶：buckets[桶号][桶内位置]
// 用二维数组当桶最直观。缺点是空间是 r × n，比较浪费。
    ElementType buckets[RADIX][MAXN];
// 每个桶里现在有多少个元素
    int count[RADIX];
// 收集结果
    ElementType tmp[MAXN];
// 第几轮（也就是第几位）
    int d;
// 循环用
    int i, j;
// 当前元素应该进哪个桶
    int di;
// 收集时的写入位置
    int pos;

// 一共做 MAXD 轮：个位、十位、百位、千位
    for (d = 1; d <= MAXD; d++)
    {
// ① 清空所有桶的计数
        for (i = 0; i < RADIX; i++)
        {
            count[i] = 0;
        }

// ② 分配：按第 d 位把元素扔进桶里
        for (i = 0; i < N; i++)
        {
// 取第 d 位
            di = GetDigit(A[i], d);
// 放进对应的桶，桶计数加一
// `count[di]++` 是先用当前值当位置，再加一 —— 这就是"先进先出"的保证。
            buckets[di][count[di]++] = A[i];
        }

// ③ 收集：按桶号 0~9，把每个桶里的元素依次取回来
        pos = 0;
        for (i = 0; i < RADIX; i++)
        {
            for (j = 0; j < count[i]; j++)
            {
// 从桶里取元素 —— 同桶内是先进先出，所以这一轮是稳定的
                tmp[pos++] = buckets[i][j];
            }
        }

// ④ 把这一轮的结果写回原数组，供下一轮使用
        for (i = 0; i < N; i++)
        {
            A[i] = tmp[i];
        }
    }
}

// ummary | 打印数组、检查是否有序。
// 表排序有个特殊的输出方式：既打印元素本身，也打印 table 指出的顺序。
// 因为"表排序之后数组是乱的，但按 table 读是有序的" —— 这一点必须看清楚。

void PrintArray(const ElementType A[], int N)
{
// 循环用
    int i;

    printf("[");
    for (i = 0; i < N; i++)
    {
        printf("%d", A[i]);
        if (i < N - 1)
        {
            printf(", ");
        }
    }
    printf("]");
}

// 检查是否有序
int IsSorted(const ElementType A[], int N)
{
// 循环用
    int i;

    for (i = 0; i + 1 < N; i++)
    {
        if (A[i] > A[i + 1])
        {
            return 0;
        }
    }
    return 1;
}

// 按 table 给出的顺序打印元素
// 这是表排序的正确读法：数组本身乱着，但按 table 读出来是有序的。
void PrintByTable(const ElementType A[], int table[], int N)
{
// 循环用
    int i;

    printf("[");
    for (i = 0; i < N; i++)
    {
// 绕一层 table 去访问元素
        printf("%d", A[table[i]]);
        if (i < N - 1)
        {
            printf(", ");
        }
    }
    printf("]");
}

// 检查"按 table 读出来"是不是有序
int IsSortedByTable(const ElementType A[], int table[], int N)
{
// 循环用
    int i;

    for (i = 0; i + 1 < N; i++)
    {
        if (A[table[i]] > A[table[i + 1]])
        {
            return 0;
        }
    }
    return 1;
}

// ============ 怎么看这两个算法 ============
//
// **表排序**的重点是：跑完之后 `A` 本身还是乱的，但 `A[table[0]]`、
// `A[table[1]]`…… 读出来是有序的。这就是"间接排序"。
//
// **基数排序**的重点是：整个过程一次比较都没有，只有"取某一位"和
// "分桶收集"。所以它的复杂度里没有 log n。

// 主函数
int main(void)
{
// 表排序的测试数据
    ElementType a[] = { 30, 10, 40, 20, 50 };
// table
    int table[5];
// 基数排序的测试数据
    ElementType b[] = { 1234, 5, 21, 0, 99, 1000, 7, 456 };
// 长度
    int nb = 8;
// 循环用
    int i;

// ===== 表排序 =====
    printf("=== 表排序 ===\n");
    printf("原始 A: ");
    PrintArray(a, 5);
    printf("\n\n");

    TableSort(a, 5, table);

    printf("排完之后 A 本身: ");
    PrintArray(a, 5);
    printf("   ← 一个都没动！\n");
    printf("table:           [");
    for (i = 0; i < 5; i++)
    {
        printf("%d%s", table[i], i < 4 ? ", " : "");
    }
    printf("]\n");
    printf("按 table 读 A:   ");
    PrintByTable(a, table, 5);
    printf("   ← 有序了\n");
    printf("按 table 读是有序: %s\n\n", IsSortedByTable(a, table, 5) ? "是" : "不是");

// 环重排
    printf("--- 如果需要元素本身也有序，就做环重排 ---\n");
    printf("重排前 A: ");
    PrintArray(a, 5);
    printf("\n");
    Rearrange(a, 5, table);
    printf("重排后 A: ");
    PrintArray(a, 5);
    printf("   %s\n", IsSorted(a, 5) ? "有序 ✓" : "还是乱的 ✗");
    printf("（环移动是原地完成的，不需要额外数组）\n\n");

// ===== 基数排序 =====
    printf("=== 基数排序 ===\n");
    printf("原始: ");
    PrintArray(b, nb);
    printf("\n");
    printf("（最大 4 位数，所以做 4 轮：个位 → 十位 → 百位 → 千位）\n\n");

// 手工演示前两轮
    {
        ElementType c[MAXN];
        int count[RADIX];
        ElementType buckets[RADIX][MAXN];
        ElementType tmp[MAXN];
        int d, j, di, pos;

        for (i = 0; i < nb; i++) c[i] = b[i];

        for (d = 1; d <= 2; d++)
        {
            for (i = 0; i < RADIX; i++) count[i] = 0;
            for (i = 0; i < nb; i++)
            {
                di = GetDigit(c[i], d);
                buckets[di][count[di]++] = c[i];
            }
            pos = 0;
            for (i = 0; i < RADIX; i++)
            {
                for (j = 0; j < count[i]; j++) tmp[pos++] = buckets[i][j];
            }
            for (i = 0; i < nb; i++) c[i] = tmp[i];

            printf("第 %d 轮（看%s位）之后: ", d, d == 1 ? "个" : "十");
            PrintArray(c, nb);
            printf("\n");
        }
        printf("\n");
    }

// 完整跑一遍
    RadixSort(b, nb);
    printf("排完: ");
    PrintArray(b, nb);
    printf("   %s\n", IsSorted(b, nb) ? "有序 ✓" : "还是乱的 ✗");

// 总结
    printf("\n=== 两个算法的共同点：绕开 O(n log n) ===\n");
    printf("  表排序  ：比较的本质没变，但「搬动」的代价从几百字节降到 4 字节\n");
    printf("  基数排序：**完全不比较**，靠逐位分桶，O(d(n+r))\n");
    printf("\n基数排序为什么是对的？因为「分配-收集」是稳定的，\n");
    printf("所以低位排好的顺序在高位相同时不会被打乱。\n");
    printf("（这也是它必须用稳定排序的原因）\n");

// 正常结束
    return 0;
}

