#include <stdio.h>
#include <stdlib.h>


// 元素类型
typedef int ElementType;

// 基数：十进制数每一位有 10 种可能（0~9）
#define RADIX 10

// 最大位数：本节的测试数据最大 9999，所以是 4 位
#define MAXD 4

// 数组的最大长度（桶要用）
#define MAXN 100

// 状态码
#define OK 1
#define ERROR 0
typedef int Status;


// 表排序：把"访问顺序"排进 table，A 本身不动
void TableSort(ElementType A[], int N, int table[])
{
// 循环用
    int i, j;
// 临时存一个下标
    int tmp;

// 初始化：一开始"第 i 小的就是第 i 个"
    for (i = 0; i < N; i++)
    {
        table[i] = i;
    }

// 用插入排序的框架，对 table 排序
    for (i = 1; i < N; i++)
    {
// 取出当前下标
        tmp = table[i];

// 比较时套一层 table —— 注意这里是 A[table[j-1]] 和 A[tmp]
        for (j = i; j > 0 && A[table[j - 1]] > A[tmp]; j--)
        {
// 搬动的是下标，不是元素
            table[j] = table[j - 1];
        }

// 下标落位
        table[j] = tmp;
    }
}


// 按 table 把 A 重排成物理有序（原地，用环移动）
void Rearrange(ElementType A[], int N, int table[])
{
// 循环用
    int i, k, next;
// 暂存元素
    ElementType tmp;

    for (i = 0; i < N; i++)
    {
// table[i] == i 说明这个位置已经对了，跳过
        if (table[i] != i)
        {
// 把位置 i 的元素先抱出来——它要搬到别处去
            tmp = A[i];
            k = i;

// 沿着环往前推，直到绕回起点
            while (table[k] != i)
            {
// 把"应该放到 k 位置"的那个元素搬过来
                A[k] = A[table[k]];

// 记住当前位置，然后跳到下一个
                next = k;
                k = table[k];

// 这个位置处理完了，标记成"已就位"
                table[next] = next;
            }

// 环绕回来了，把最开始抱出来的元素放进空位
            A[k] = tmp;
            table[k] = k;
        }
    }
}


// 取非负整数 x 的第 d 位（d 从 1 开始，d=1 是个位）
int GetDigit(int x, int d)
{
// 循环用
    int i;

// 先把低 d-1 位除掉
    for (i = 1; i < d; i++)
    {
        x /= 10;
    }

// 取个位
    return x % RADIX;
}


// 基数排序（低位优先）
void RadixSort(ElementType A[], int N)
{
// 桶：buckets[桶号][桶内位置]
    ElementType buckets[RADIX][MAXN];
// 每个桶里现在有多少个元素
    int count[RADIX];
// 收集结果
    ElementType tmp[MAXN];
// 第几轮（也就是第几位）
    int d;
// 循环用
    int i, j;
// 当前元素应该进哪个桶
    int di;
// 收集时的写入位置
    int pos;

// 一共做 MAXD 轮：个位、十位、百位、千位
    for (d = 1; d <= MAXD; d++)
    {
// ① 清空所有桶的计数
        for (i = 0; i < RADIX; i++)
        {
            count[i] = 0;
        }

// ② 分配：按第 d 位把元素扔进桶里
        for (i = 0; i < N; i++)
        {
// 取第 d 位
            di = GetDigit(A[i], d);
// 放进对应的桶，桶计数加一
            buckets[di][count[di]++] = A[i];
        }

// ③ 收集：按桶号 0~9，把每个桶里的元素依次取回来
        pos = 0;
        for (i = 0; i < RADIX; i++)
        {
            for (j = 0; j < count[i]; j++)
            {
// 从桶里取元素 —— 同桶内是先进先出，所以这一轮是稳定的
                tmp[pos++] = buckets[i][j];
            }
        }

// ④ 把这一轮的结果写回原数组，供下一轮使用
        for (i = 0; i < N; i++)
        {
            A[i] = tmp[i];
        }
    }
}

// ummary | 打印数组、检查是否有序。

void PrintArray(const ElementType A[], int N)
