            {
                di = GetDigit(c[i], d);
                buckets[di][count[di]++] = c[i];
            }
            pos = 0;
            for (i = 0; i < RADIX; i++)
            {
                for (j = 0; j < count[i]; j++) tmp[pos++] = buckets[i][j];
            }
            for (i = 0; i < nb; i++) c[i] = tmp[i];

            printf("第 %d 轮（看%s位）之后: ", d, d == 1 ? "个" : "十");
            PrintArray(c, nb);
            printf("\n");
        }
        printf("\n");
    }

    RadixSort(b, nb);
    printf("排完: ");
    PrintArray(b, nb);
    printf("   %s\n", IsSorted(b, nb) ? "有序 ✓" : "还是乱的 ✗");

    printf("\n=== 两个算法的共同点：绕开 O(n log n) ===\n");
    printf("  表排序  ：比较的本质没变，但「搬动」的代价从几百字节降到 4 字节\n");
    printf("  基数排序：**完全不比较**，靠逐位分桶，O(d(n+r))\n");
    printf("\n基数排序为什么是对的？因为「分配-收集」是稳定的，\n");
    printf("所以低位排好的顺序在高位相同时不会被打乱。\n");
    printf("（这也是它必须用稳定排序的原因）\n");

    return 0;
}
